const sections=rows=>{const groups=new Map();for(const item of rows){const label=String(item.category||'Pilihan').trim()||'Pilihan';if(!groups.has(label))groups.set(label,[]);groups.get(label).push(item);}const out=[];for(const [label,items] of groups){for(let i=0;i<items.length;i+=8){out.push({title:items.length>8?`${label} ${Math.floor(i/8)+1}`:label,rows:items.slice(i,i+8).map(({category,...r})=>r)});}}return out;};
