async function sendList(ctx,title,subtitle,body,rows,extra=[]){return ctx.sendInteractive({title,subtitle,body,footer:'Pilih opsi melalui tombol daftar. Perubahan disimpan per pengguna.',buttons:[...extra,{name:'single_select',title:'Pilih Pengaturan',sections:sections(rows)}]});}
async function fontPicker(ctx,current){const rows=FONTS.map(([id,name,desc,preview],i)=>({title:`${String(i+1).padStart(2,'0')}. ${name}${id===current?' ✓':''}`,description:`${desc}\n${preview}`,id:`${ctx.prefix}setmenu font ${id}`}));return sendList(ctx,'Font Menu','Pilih font bernomor dengan preview',`Font aktif: ${current}\nFont diterapkan ke judul, paragraf, nomor, isi, kategori dan footer.`,rows,[{name:'quick_reply',title:'Kembali',id:`${ctx.prefix}setmenu`}]);}
async function boldPicker(ctx,settings){const active=new Set(settings.boldParts||[]);const rows=BOLD_PARTS.map(([id,name])=>row(ctx,`${active.has(id)?'☑':'☐'} ${name}`,`Tebal ${name.toLowerCase()}: ${active.has(id)?'aktif':'nonaktif'}`,`setmenu bold ${id} ${active.has(id)?'off':'on'}`));rows.unshift(row(ctx,'Aktifkan semua','Tebalkan semua bagian','setmenu bold all on'),row(ctx,'Nonaktifkan semua','Kembalikan semua bagian ke ketebalan normal','setmenu bold all off'));return sendList(ctx,'Ketebalan Font','Pilih bagian yang ingin ditebalkan',`Bagian tebal aktif: ${active.size}/${BOLD_PARTS.length}. Pengaturan berlaku dari bagian atas sampai bawah menu.`,rows,[{name:'quick_reply',title:'Kembali ke Pengaturan Utama',id:`${ctx.prefix}setmenu`}]);}
async function widgetPicker(ctx,settings){const rows=WIDGETS.map(([id,name,desc])=>row(ctx,`${settings.widgets.includes(id)?'☑':'☐'} ${name}`,`${desc}\nStatus: ${settings.widgets.includes(id)?'Tampil':'Disembunyikan'}`,`setmenu widget ${id} ${settings.widgets.includes(id)?'off':'on'}`));rows.unshift(row(ctx,'Tampilkan semua widget','Aktifkan seluruh komponen menu','setmenu widget all on'),row(ctx,'Sembunyikan semua widget','Nonaktifkan seluruh komponen menu','setmenu widget all off'));return sendList(ctx,'Widget Menu','Pilih komponen satu per satu',`Widget aktif: ${(settings.widgets||[]).length}/${WIDGETS.length}\nPilih item untuk mengubah statusnya. Kategori, jumlah, prefix, penanda baru, owner, judul, paragraf dan footer dikendalikan terpisah.`,rows,[{name:'quick_reply',title:'Kembali ke Pengaturan',id:`${ctx.prefix}setmenu`}]);}
